-- Reference data (A-6). Fixed UUIDs so README examples and tests can refer to them.
-- Prefixes: d = dealership, b = service bay, a = technician, c = service type.


-- ISO day of week: 1 = Monday ... 7 = Sunday. No row for Sunday means closed.
SELECT d.id, dow, time '08:00', CASE WHEN dow = 6 THEN time '12:00' ELSE time '17:00' END
FROM dealership d
CROSS JOIN generate_series(1, 6) AS dow
WHERE d.id IN ('d0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000002');




-- Every technician: oil change (c..01) and tire rotation (c..02). Technicians 1-2: brake service (c..03).
-- Only technician 1 per dealership: full inspection (c..04), which exercises the single-candidate path.
